CREATE OR REPLACE PROCEDURE STAGING.RUN_PIPELINE(P_REPLACE BOOLEAN)
RETURNS STRING
LANGUAGE SQL
EXECUTE AS OWNER
AS
$$
DECLARE
  run_id STRING;
BEGIN
  run_id := UUID_STRING();
  IF (P_REPLACE) THEN
    DELETE FROM CURATED.BILLING;
    DELETE FROM CURATED.EXPENSES;
    DELETE FROM CURATED.DEPT_BUDGETS;
    DELETE FROM CURATED.MAINTENANCE;
    DELETE FROM CURATED.EQUIPMENT;
    DELETE FROM CURATED.DISPENSING;
    DELETE FROM CURATED.PURCHASES;
    DELETE FROM CURATED.STOCK_BATCHES;
    DELETE FROM CURATED.DEATH_RECORDS;
    DELETE FROM CURATED.SURGERY_OUTCOMES;
    DELETE FROM CURATED.SURGERIES;
    DELETE FROM CURATED.RADIOLOGY_REPORTS;
    DELETE FROM CURATED.IMAGING_STUDIES;
    DELETE FROM CURATED.PATHOLOGY_REPORTS;
    DELETE FROM CURATED.LAB_RESULTS;
    DELETE FROM CURATED.SPECIMENS;
    DELETE FROM CURATED.LAB_ORDERS;
    DELETE FROM CURATED.LAB_TEST_CATALOG;
    DELETE FROM CURATED.MEDICATION_ORDERS;
    DELETE FROM CURATED.PRESCRIPTIONS;
    DELETE FROM CURATED.DRUGS;
    DELETE FROM CURATED.SUPPLIERS;
    DELETE FROM CURATED.MANUFACTURERS;
