    DELETE FROM CURATED.DIAGNOSES;
    DELETE FROM CURATED.ENCOUNTERS;
    DELETE FROM CURATED.ALLERGIES;
    DELETE FROM CURATED.PATIENTS;
    DELETE FROM CURATED.PAYROLL;
    DELETE FROM CURATED.SHIFTS;
    DELETE FROM CURATED.NURSES;
    DELETE FROM CURATED.DOCTORS;
    DELETE FROM CURATED.STAFF;
    DELETE FROM CURATED.DEPARTMENTS;
    DELETE FROM CURATED.SPECIALTIES;
  END IF;
  CREATE OR REPLACE TABLE STAGING.SPECIALTIES AS
    SELECT
      NULLIF(TRIM("SPECIALTY_ID"), '') AS "SPECIALTY_ID",
      NULLIF(TRIM("SPECIALTY_NAME"), '') AS "SPECIALTY_NAME",
      ARRAY_CONSTRUCT_COMPACT(NULL) AS _CAST_FAIL,
      ROW_NUMBER() OVER (ORDER BY _FILE, "SPECIALTY_ID") AS _ROW_NUM,
      _FILE
    FROM RAW.SPECIALTIES;
  INSERT INTO STAGING.DQ_ISSUES (RUN_ID, TABLE_NAME, RECORD_ID, ROW_NUM, RULE_CODE, COLUMN_NAME, SEVERITY, DETAILS)
    SELECT :run_id, 'SPECIALTIES', "SPECIALTY_ID", _ROW_NUM, 'REQUIRED_MISSING', 'specialty_id', 'ERROR', 'Required field is empty'
    FROM STAGING.SPECIALTIES WHERE "SPECIALTY_ID" IS NULL AND NOT ARRAY_CONTAINS('specialty_id'::VARIANT, _CAST_FAIL);
  INSERT INTO STAGING.DQ_ISSUES (RUN_ID, TABLE_NAME, RECORD_ID, ROW_NUM, RULE_CODE, COLUMN_NAME, SEVERITY, DETAILS)
    SELECT :run_id, 'SPECIALTIES', "SPECIALTY_ID", _ROW_NUM, 'REQUIRED_MISSING', 'specialty_name', 'ERROR', 'Required field is empty'
    FROM STAGING.SPECIALTIES WHERE "SPECIALTY_NAME" IS NULL AND NOT ARRAY_CONTAINS('specialty_name'::VARIANT, _CAST_FAIL);
