    FROM STAGING.SPECIALTIES WHERE "SPECIALTY_ID" IS NOT NULL
    QUALIFY ROW_NUMBER() OVER (PARTITION BY "SPECIALTY_ID" ORDER BY _ROW_NUM) > 1;
  INSERT INTO CURATED.SPECIALTIES ("SPECIALTY_ID", "SPECIALTY_NAME")
    SELECT "SPECIALTY_ID", "SPECIALTY_NAME" FROM STAGING.SPECIALTIES s
    WHERE NOT EXISTS (SELECT 1 FROM STAGING.DQ_ISSUES i
                      WHERE i.RUN_ID = :run_id AND i.TABLE_NAME = 'SPECIALTIES' AND i.SEVERITY = 'ERROR'
                        AND i.ROW_NUM = s._ROW_NUM)
      AND NOT EXISTS (SELECT 1 FROM CURATED.SPECIALTIES c WHERE c."SPECIALTY_ID" = s."SPECIALTY_ID");
  INSERT INTO STAGING.PIPELINE_RUNS (RUN_ID, TABLE_NAME, RAW_ROWS, CURATED_ROWS, ERROR_ROWS)
    SELECT :run_id, 'SPECIALTIES',
      (SELECT COUNT(*) FROM STAGING.SPECIALTIES),
      (SELECT COUNT(*) FROM CURATED.SPECIALTIES),
      (SELECT COUNT(DISTINCT ROW_NUM) FROM STAGING.DQ_ISSUES WHERE RUN_ID = :run_id AND TABLE_NAME = 'SPECIALTIES' AND SEVERITY = 'ERROR');
  CREATE OR REPLACE TABLE STAGING.DEPARTMENTS AS
    SELECT
      NULLIF(TRIM("DEPARTMENT_ID"), '') AS "DEPARTMENT_ID",
      NULLIF(TRIM("DEPARTMENT_NAME"), '') AS "DEPARTMENT_NAME",
      NULLIF(TRIM("SPECIALTY_ID"), '') AS "SPECIALTY_ID",
      TRY_TO_NUMBER(NULLIF(TRIM("FLOOR"), '')) AS "FLOOR",
      TRY_TO_NUMBER(NULLIF(TRIM("BED_CAPACITY"), '')) AS "BED_CAPACITY",
      ARRAY_CONSTRUCT_COMPACT(IFF(NULLIF(TRIM("FLOOR"), '') IS NOT NULL AND TRY_TO_NUMBER(NULLIF(TRIM("FLOOR"), '')) IS NULL, 'floor', NULL), IFF(NULLIF(TRIM("BED_CAPACITY"), '') IS NOT NULL AND TRY_TO_NUMBER(NULLIF(TRIM("BED_CAPACITY"), '')) IS NULL, 'bed_capacity', NULL)) AS _CAST_FAIL,
      ROW_NUMBER() OVER (ORDER BY _FILE, "DEPARTMENT_ID") AS _ROW_NUM,
      _FILE
    FROM RAW.DEPARTMENTS;
