  CREATE OR REPLACE TABLE STAGING.STAFF AS
    SELECT
      NULLIF(TRIM("STAFF_ID"), '') AS "STAFF_ID",
      NULLIF(TRIM("FIRST_NAME"), '') AS "FIRST_NAME",
      NULLIF(TRIM("LAST_NAME"), '') AS "LAST_NAME",
      NULLIF(TRIM("ROLE"), '') AS "ROLE",
      NULLIF(TRIM("DEPARTMENT_ID"), '') AS "DEPARTMENT_ID",
      TRY_TO_DATE(NULLIF(TRIM("HIRE_DATE"), ''), 'YYYY-MM-DD') AS "HIRE_DATE",
      NULLIF(TRIM("EMPLOYMENT_STATUS"), '') AS "EMPLOYMENT_STATUS",
      NULLIF(TRIM("EMAIL"), '') AS "EMAIL",
      TRY_TO_DECIMAL(NULLIF(TRIM("BASE_SALARY"), ''), 14, 2) AS "BASE_SALARY",
      ARRAY_CONSTRUCT_COMPACT(IFF(NULLIF(TRIM("HIRE_DATE"), '') IS NOT NULL AND TRY_TO_DATE(NULLIF(TRIM("HIRE_DATE"), ''), 'YYYY-MM-DD') IS NULL, 'hire_date', NULL), IFF(NULLIF(TRIM("BASE_SALARY"), '') IS NOT NULL AND TRY_TO_DECIMAL(NULLIF(TRIM("BASE_SALARY"), ''), 14, 2) IS NULL, 'base_salary', NULL)) AS _CAST_FAIL,
      ROW_NUMBER() OVER (ORDER BY _FILE, "STAFF_ID") AS _ROW_NUM,
