  CREATE OR REPLACE TABLE STAGING.SHIFTS AS
    SELECT
      NULLIF(TRIM("SHIFT_ID"), '') AS "SHIFT_ID",
      NULLIF(TRIM("STAFF_ID"), '') AS "STAFF_ID",
      NULLIF(TRIM("DEPARTMENT_ID"), '') AS "DEPARTMENT_ID",
      NULLIF(TRIM("SHIFT_TYPE"), '') AS "SHIFT_TYPE",
      TRY_TO_TIMESTAMP_NTZ(NULLIF(TRIM("START_TS"), '')) AS "START_TS",
      TRY_TO_TIMESTAMP_NTZ(NULLIF(TRIM("END_TS"), '')) AS "END_TS",
      NULLIF(TRIM("STATUS"), '') AS "STATUS",
      ARRAY_CONSTRUCT_COMPACT(IFF(NULLIF(TRIM("START_TS"), '') IS NOT NULL AND TRY_TO_TIMESTAMP_NTZ(NULLIF(TRIM("START_TS"), '')) IS NULL, 'start_ts', NULL), IFF(NULLIF(TRIM("END_TS"), '') IS NOT NULL AND TRY_TO_TIMESTAMP_NTZ(NULLIF(TRIM("END_TS"), '')) IS NULL, 'end_ts', NULL)) AS _CAST_FAIL,
      ROW_NUMBER() OVER (ORDER BY _FILE, "SHIFT_ID") AS _ROW_NUM,
      _FILE
