  CREATE OR REPLACE TABLE STAGING.PAYROLL AS
    SELECT
      NULLIF(TRIM("PAYROLL_ID"), '') AS "PAYROLL_ID",
      NULLIF(TRIM("STAFF_ID"), '') AS "STAFF_ID",
      NULLIF(TRIM("PAY_PERIOD"), '') AS "PAY_PERIOD",
      TRY_TO_DECIMAL(NULLIF(TRIM("GROSS_PAY"), ''), 14, 2) AS "GROSS_PAY",
      TRY_TO_DECIMAL(NULLIF(TRIM("OVERTIME_PAY"), ''), 14, 2) AS "OVERTIME_PAY",
      TRY_TO_DECIMAL(NULLIF(TRIM("DEDUCTIONS"), ''), 14, 2) AS "DEDUCTIONS",
      ARRAY_CONSTRUCT_COMPACT(IFF(NULLIF(TRIM("GROSS_PAY"), '') IS NOT NULL AND TRY_TO_DECIMAL(NULLIF(TRIM("GROSS_PAY"), ''), 14, 2) IS NULL, 'gross_pay', NULL), IFF(NULLIF(TRIM("OVERTIME_PAY"), '') IS NOT NULL AND TRY_TO_DECIMAL(NULLIF(TRIM("OVERTIME_PAY"), ''), 14, 2) IS NULL, 'overtime_pay', NULL), IFF(NULLIF(TRIM("DEDUCTIONS"), '') IS NOT NULL AND TRY_TO_DECIMAL(NULLIF(TRIM("DEDUCTIONS"), ''), 14, 2) IS NULL, 'deductions', NULL)) AS _CAST_FAIL,
      ROW_NUMBER() OVER (ORDER BY _FILE, "PAYROLL_ID") AS _ROW_NUM,
      _FILE
    FROM RAW.PAYROLL;
