    SELECT "PATIENT_ID", "FIRST_NAME", "LAST_NAME", "DATE_OF_BIRTH", "SEX", "BLOOD_TYPE", "CITY", "PHONE", "EMAIL", "PRIMARY_SPECIALTY_ID", "REGISTERED_ON" FROM STAGING.PATIENTS s
