  CREATE OR REPLACE TABLE STAGING.ENCOUNTERS AS
    SELECT
      NULLIF(TRIM("ENCOUNTER_ID"), '') AS "ENCOUNTER_ID",
      NULLIF(TRIM("PATIENT_ID"), '') AS "PATIENT_ID",
      NULLIF(TRIM("DOCTOR_ID"), '') AS "DOCTOR_ID",
      NULLIF(TRIM("DEPARTMENT_ID"), '') AS "DEPARTMENT_ID",
      NULLIF(TRIM("ENCOUNTER_TYPE"), '') AS "ENCOUNTER_TYPE",
      TRY_TO_DATE(NULLIF(TRIM("ADMIT_DATE"), ''), 'YYYY-MM-DD') AS "ADMIT_DATE",
      TRY_TO_DATE(NULLIF(TRIM("DISCHARGE_DATE"), ''), 'YYYY-MM-DD') AS "DISCHARGE_DATE",
      NULLIF(TRIM("STATUS"), '') AS "STATUS",
      ARRAY_CONSTRUCT_COMPACT(IFF(NULLIF(TRIM("ADMIT_DATE"), '') IS NOT NULL AND TRY_TO_DATE(NULLIF(TRIM("ADMIT_DATE"), ''), 'YYYY-MM-DD') IS NULL, 'admit_date', NULL), IFF(NULLIF(TRIM("DISCHARGE_DATE"), '') IS NOT NULL AND TRY_TO_DATE(NULLIF(TRIM("DISCHARGE_DATE"), ''), 'YYYY-MM-DD') IS NULL, 'discharge_date', NULL)) AS _CAST_FAIL,
      ROW_NUMBER() OVER (ORDER BY _FILE, "ENCOUNTER_ID") AS _ROW_NUM,
      _FILE
    FROM RAW.ENCOUNTERS;
