  CREATE OR REPLACE TABLE STAGING.DIAGNOSES AS
    SELECT
      NULLIF(TRIM("DIAGNOSIS_ID"), '') AS "DIAGNOSIS_ID",
      NULLIF(TRIM("ENCOUNTER_ID"), '') AS "ENCOUNTER_ID",
      NULLIF(TRIM("ICD10_CODE"), '') AS "ICD10_CODE",
      NULLIF(TRIM("DESCRIPTION"), '') AS "DESCRIPTION",
      IFF(NULLIF(TRIM("IS_PRIMARY"), '') IN ('1','true','TRUE'), TRUE, IFF(NULLIF(TRIM("IS_PRIMARY"), '') IN ('0','false','FALSE'), FALSE, NULL)) AS "IS_PRIMARY",
      IFF(NULLIF(TRIM("IS_SENSITIVE"), '') IN ('1','true','TRUE'), TRUE, IFF(NULLIF(TRIM("IS_SENSITIVE"), '') IN ('0','false','FALSE'), FALSE, NULL)) AS "IS_SENSITIVE",
      ARRAY_CONSTRUCT_COMPACT(IFF(NULLIF(TRIM("IS_PRIMARY"), '') IS NOT NULL AND IFF(NULLIF(TRIM("IS_PRIMARY"), '') IN ('1','true','TRUE'), TRUE, IFF(NULLIF(TRIM("IS_PRIMARY"), '') IN ('0','false','FALSE'), FALSE, NULL)) IS NULL, 'is_primary', NULL), IFF(NULLIF(TRIM("IS_SENSITIVE"), '') IS NOT NULL AND IFF(NULLIF(TRIM("IS_SENSITIVE"), '') IN ('1','true','TRUE'), TRUE, IFF(NULLIF(TRIM("IS_SENSITIVE"), '') IN ('0','false','FALSE'), FALSE, NULL)) IS NULL, 'is_sensitive', NULL)) AS _CAST_FAIL,
      ROW_NUMBER() OVER (ORDER BY _FILE, "DIAGNOSIS_ID") AS _ROW_NUM,
      _FILE
    FROM RAW.DIAGNOSES;
  INSERT INTO STAGING.DQ_ISSUES (RUN_ID, TABLE_NAME, RECORD_ID, ROW_NUM, RULE_CODE, COLUMN_NAME, SEVERITY, DETAILS)
