  CREATE OR REPLACE TABLE STAGING.SUPPLIERS AS
    SELECT
      NULLIF(TRIM("SUPPLIER_ID"), '') AS "SUPPLIER_ID",
      NULLIF(TRIM("NAME"), '') AS "NAME",
      NULLIF(TRIM("CONTACT_EMAIL"), '') AS "CONTACT_EMAIL",
      TRY_TO_NUMBER(NULLIF(TRIM("LEAD_TIME_DAYS"), '')) AS "LEAD_TIME_DAYS",
      TRY_TO_DECIMAL(NULLIF(TRIM("RATING"), ''), 14, 2) AS "RATING",
      ARRAY_CONSTRUCT_COMPACT(IFF(NULLIF(TRIM("LEAD_TIME_DAYS"), '') IS NOT NULL AND TRY_TO_NUMBER(NULLIF(TRIM("LEAD_TIME_DAYS"), '')) IS NULL, 'lead_time_days', NULL), IFF(NULLIF(TRIM("RATING"), '') IS NOT NULL AND TRY_TO_DECIMAL(NULLIF(TRIM("RATING"), ''), 14, 2) IS NULL, 'rating', NULL)) AS _CAST_FAIL,
      ROW_NUMBER() OVER (ORDER BY _FILE, "SUPPLIER_ID") AS _ROW_NUM,
      _FILE
    FROM RAW.SUPPLIERS;
