  CREATE OR REPLACE TABLE STAGING.DRUGS AS
    SELECT
      NULLIF(TRIM("DRUG_ID"), '') AS "DRUG_ID",
      NULLIF(TRIM("DRUG_NAME"), '') AS "DRUG_NAME",
      NULLIF(TRIM("GENERIC_NAME"), '') AS "GENERIC_NAME",
      NULLIF(TRIM("FORM"), '') AS "FORM",
      NULLIF(TRIM("MANUFACTURER_ID"), '') AS "MANUFACTURER_ID",
      TRY_TO_DECIMAL(NULLIF(TRIM("UNIT_PRICE"), ''), 14, 2) AS "UNIT_PRICE",
      TRY_TO_NUMBER(NULLIF(TRIM("REORDER_LEVEL"), '')) AS "REORDER_LEVEL",
      IFF(NULLIF(TRIM("IS_CONTROLLED"), '') IN ('1','true','TRUE'), TRUE, IFF(NULLIF(TRIM("IS_CONTROLLED"), '') IN ('0','false','FALSE'), FALSE, NULL)) AS "IS_CONTROLLED",
      ARRAY_CONSTRUCT_COMPACT(IFF(NULLIF(TRIM("UNIT_PRICE"), '') IS NOT NULL AND TRY_TO_DECIMAL(NULLIF(TRIM("UNIT_PRICE"), ''), 14, 2) IS NULL, 'unit_price', NULL), IFF(NULLIF(TRIM("REORDER_LEVEL"), '') IS NOT NULL AND TRY_TO_NUMBER(NULLIF(TRIM("REORDER_LEVEL"), '')) IS NULL, 'reorder_level', NULL), IFF(NULLIF(TRIM("IS_CONTROLLED"), '') IS NOT NULL AND IFF(NULLIF(TRIM("IS_CONTROLLED"), '') IN ('1','true','TRUE'), TRUE, IFF(NULLIF(TRIM("IS_CONTROLLED"), '') IN ('0','false','FALSE'), FALSE, NULL)) IS NULL, 'is_controlled', NULL)) AS _CAST_FAIL,
      ROW_NUMBER() OVER (ORDER BY _FILE, "DRUG_ID") AS _ROW_NUM,
      _FILE
    FROM RAW.DRUGS;
