  CREATE OR REPLACE TABLE STAGING.LAB_TEST_CATALOG AS
    SELECT
      NULLIF(TRIM("TEST_CODE"), '') AS "TEST_CODE",
      NULLIF(TRIM("TEST_NAME"), '') AS "TEST_NAME",
      NULLIF(TRIM("UNIT"), '') AS "UNIT",
      TRY_TO_DECIMAL(NULLIF(TRIM("REF_LOW"), ''), 14, 2) AS "REF_LOW",
      TRY_TO_DECIMAL(NULLIF(TRIM("REF_HIGH"), ''), 14, 2) AS "REF_HIGH",
      NULLIF(TRIM("SPECIMEN_TYPE"), '') AS "SPECIMEN_TYPE",
      ARRAY_CONSTRUCT_COMPACT(IFF(NULLIF(TRIM("REF_LOW"), '') IS NOT NULL AND TRY_TO_DECIMAL(NULLIF(TRIM("REF_LOW"), ''), 14, 2) IS NULL, 'ref_low', NULL), IFF(NULLIF(TRIM("REF_HIGH"), '') IS NOT NULL AND TRY_TO_DECIMAL(NULLIF(TRIM("REF_HIGH"), ''), 14, 2) IS NULL, 'ref_high', NULL)) AS _CAST_FAIL,
      ROW_NUMBER() OVER (ORDER BY _FILE, "TEST_CODE") AS _ROW_NUM,
      _FILE
    FROM RAW.LAB_TEST_CATALOG;
