  CREATE OR REPLACE TABLE STAGING.LAB_RESULTS AS
    SELECT
      NULLIF(TRIM("RESULT_ID"), '') AS "RESULT_ID",
      NULLIF(TRIM("LAB_ORDER_ID"), '') AS "LAB_ORDER_ID",
      NULLIF(TRIM("SPECIMEN_ID"), '') AS "SPECIMEN_ID",
      NULLIF(TRIM("TEST_CODE"), '') AS "TEST_CODE",
      TRY_TO_DECIMAL(NULLIF(TRIM("VALUE"), ''), 14, 2) AS "VALUE",
      NULLIF(TRIM("FLAG"), '') AS "FLAG",
      TRY_TO_TIMESTAMP_NTZ(NULLIF(TRIM("RESULTED_TS"), '')) AS "RESULTED_TS",
      NULLIF(TRIM("VERIFIED_BY_STAFF_ID"), '') AS "VERIFIED_BY_STAFF_ID",
      ARRAY_CONSTRUCT_COMPACT(IFF(NULLIF(TRIM("VALUE"), '') IS NOT NULL AND TRY_TO_DECIMAL(NULLIF(TRIM("VALUE"), ''), 14, 2) IS NULL, 'value', NULL), IFF(NULLIF(TRIM("RESULTED_TS"), '') IS NOT NULL AND TRY_TO_TIMESTAMP_NTZ(NULLIF(TRIM("RESULTED_TS"), '')) IS NULL, 'resulted_ts', NULL)) AS _CAST_FAIL,
      ROW_NUMBER() OVER (ORDER BY _FILE, "RESULT_ID") AS _ROW_NUM,
      _FILE
    FROM RAW.LAB_RESULTS;
