  CREATE OR REPLACE TABLE STAGING.SURGERIES AS
    SELECT
      NULLIF(TRIM("SURGERY_ID"), '') AS "SURGERY_ID",
      NULLIF(TRIM("ENCOUNTER_ID"), '') AS "ENCOUNTER_ID",
      NULLIF(TRIM("PATIENT_ID"), '') AS "PATIENT_ID",
      NULLIF(TRIM("SURGEON_DOCTOR_ID"), '') AS "SURGEON_DOCTOR_ID",
      NULLIF(TRIM("PROCEDURE_NAME"), '') AS "PROCEDURE_NAME",
      TRY_TO_DATE(NULLIF(TRIM("SURGERY_DATE"), ''), 'YYYY-MM-DD') AS "SURGERY_DATE",
      NULLIF(TRIM("ANESTHESIA_TYPE"), '') AS "ANESTHESIA_TYPE",
      TRY_TO_NUMBER(NULLIF(TRIM("DURATION_MIN"), '')) AS "DURATION_MIN",
      TRY_TO_DECIMAL(NULLIF(TRIM("COST"), ''), 14, 2) AS "COST",
      ARRAY_CONSTRUCT_COMPACT(IFF(NULLIF(TRIM("SURGERY_DATE"), '') IS NOT NULL AND TRY_TO_DATE(NULLIF(TRIM("SURGERY_DATE"), ''), 'YYYY-MM-DD') IS NULL, 'surgery_date', NULL), IFF(NULLIF(TRIM("DURATION_MIN"), '') IS NOT NULL AND TRY_TO_NUMBER(NULLIF(TRIM("DURATION_MIN"), '')) IS NULL, 'duration_min', NULL), IFF(NULLIF(TRIM("COST"), '') IS NOT NULL AND TRY_TO_DECIMAL(NULLIF(TRIM("COST"), ''), 14, 2) IS NULL, 'cost', NULL)) AS _CAST_FAIL,
      ROW_NUMBER() OVER (ORDER BY _FILE, "SURGERY_ID") AS _ROW_NUM,
      _FILE
    FROM RAW.SURGERIES;
