    SELECT "SURGERY_ID", "ENCOUNTER_ID", "PATIENT_ID", "SURGEON_DOCTOR_ID", "PROCEDURE_NAME", "SURGERY_DATE", "ANESTHESIA_TYPE", "DURATION_MIN", "COST" FROM STAGING.SURGERIES s
