  CREATE OR REPLACE TABLE STAGING.DEATH_RECORDS AS
    SELECT
      NULLIF(TRIM("DEATH_ID"), '') AS "DEATH_ID",
      NULLIF(TRIM("PATIENT_ID"), '') AS "PATIENT_ID",
      TRY_TO_DATE(NULLIF(TRIM("DATE_OF_DEATH"), ''), 'YYYY-MM-DD') AS "DATE_OF_DEATH",
      NULLIF(TRIM("CAUSE_ICD10"), '') AS "CAUSE_ICD10",
      NULLIF(TRIM("LOCATION"), '') AS "LOCATION",
      ARRAY_CONSTRUCT_COMPACT(IFF(NULLIF(TRIM("DATE_OF_DEATH"), '') IS NOT NULL AND TRY_TO_DATE(NULLIF(TRIM("DATE_OF_DEATH"), ''), 'YYYY-MM-DD') IS NULL, 'date_of_death', NULL)) AS _CAST_FAIL,
      ROW_NUMBER() OVER (ORDER BY _FILE, "DEATH_ID") AS _ROW_NUM,
      _FILE
    FROM RAW.DEATH_RECORDS;
