  CREATE OR REPLACE TABLE STAGING.STOCK_BATCHES AS
    SELECT
      NULLIF(TRIM("BATCH_ID"), '') AS "BATCH_ID",
      NULLIF(TRIM("DRUG_ID"), '') AS "DRUG_ID",
      NULLIF(TRIM("SUPPLIER_ID"), '') AS "SUPPLIER_ID",
      NULLIF(TRIM("LOT_NO"), '') AS "LOT_NO",
      TRY_TO_DATE(NULLIF(TRIM("RECEIVED_DATE"), ''), 'YYYY-MM-DD') AS "RECEIVED_DATE",
      TRY_TO_DATE(NULLIF(TRIM("EXPIRY_DATE"), ''), 'YYYY-MM-DD') AS "EXPIRY_DATE",
      TRY_TO_NUMBER(NULLIF(TRIM("QTY_RECEIVED"), '')) AS "QTY_RECEIVED",
      TRY_TO_NUMBER(NULLIF(TRIM("QTY_ON_HAND"), '')) AS "QTY_ON_HAND",
      ARRAY_CONSTRUCT_COMPACT(IFF(NULLIF(TRIM("RECEIVED_DATE"), '') IS NOT NULL AND TRY_TO_DATE(NULLIF(TRIM("RECEIVED_DATE"), ''), 'YYYY-MM-DD') IS NULL, 'received_date', NULL), IFF(NULLIF(TRIM("EXPIRY_DATE"), '') IS NOT NULL AND TRY_TO_DATE(NULLIF(TRIM("EXPIRY_DATE"), ''), 'YYYY-MM-DD') IS NULL, 'expiry_date', NULL), IFF(NULLIF(TRIM("QTY_RECEIVED"), '') IS NOT NULL AND TRY_TO_NUMBER(NULLIF(TRIM("QTY_RECEIVED"), '')) IS NULL, 'qty_received', NULL), IFF(NULLIF(TRIM("QTY_ON_HAND"), '') IS NOT NULL AND TRY_TO_NUMBER(NULLIF(TRIM("QTY_ON_HAND"), '')) IS NULL, 'qty_on_hand', NULL)) AS _CAST_FAIL,
      ROW_NUMBER() OVER (ORDER BY _FILE, "BATCH_ID") AS _ROW_NUM,
      _FILE
    FROM RAW.STOCK_BATCHES;
