  CREATE OR REPLACE TABLE STAGING.PURCHASES AS
    SELECT
      NULLIF(TRIM("PURCHASE_ID"), '') AS "PURCHASE_ID",
      NULLIF(TRIM("BATCH_ID"), '') AS "BATCH_ID",
      NULLIF(TRIM("SUPPLIER_ID"), '') AS "SUPPLIER_ID",
      TRY_TO_DATE(NULLIF(TRIM("ORDER_DATE"), ''), 'YYYY-MM-DD') AS "ORDER_DATE",
      TRY_TO_NUMBER(NULLIF(TRIM("QTY"), '')) AS "QTY",
      TRY_TO_DECIMAL(NULLIF(TRIM("TOTAL_COST"), ''), 14, 2) AS "TOTAL_COST",
      ARRAY_CONSTRUCT_COMPACT(IFF(NULLIF(TRIM("ORDER_DATE"), '') IS NOT NULL AND TRY_TO_DATE(NULLIF(TRIM("ORDER_DATE"), ''), 'YYYY-MM-DD') IS NULL, 'order_date', NULL), IFF(NULLIF(TRIM("QTY"), '') IS NOT NULL AND TRY_TO_NUMBER(NULLIF(TRIM("QTY"), '')) IS NULL, 'qty', NULL), IFF(NULLIF(TRIM("TOTAL_COST"), '') IS NOT NULL AND TRY_TO_DECIMAL(NULLIF(TRIM("TOTAL_COST"), ''), 14, 2) IS NULL, 'total_cost', NULL)) AS _CAST_FAIL,
      ROW_NUMBER() OVER (ORDER BY _FILE, "PURCHASE_ID") AS _ROW_NUM,
      _FILE
    FROM RAW.PURCHASES;
