    FROM STAGING.EXPENSES WHERE "EXPENSE_DATE" IS NULL AND NOT ARRAY_CONTAINS('expense_date'::VARIANT, _CAST_FAIL);
  INSERT INTO STAGING.DQ_ISSUES (RUN_ID, TABLE_NAME, RECORD_ID, ROW_NUM, RULE_CODE, COLUMN_NAME, SEVERITY, DETAILS)
    SELECT :run_id, 'EXPENSES', "EXPENSE_ID", _ROW_NUM, 'REQUIRED_MISSING', 'amount', 'ERROR', 'Required field is empty'
    FROM STAGING.EXPENSES WHERE "AMOUNT" IS NULL AND NOT ARRAY_CONTAINS('amount'::VARIANT, _CAST_FAIL);
  INSERT INTO STAGING.DQ_ISSUES (RUN_ID, TABLE_NAME, RECORD_ID, ROW_NUM, RULE_CODE, COLUMN_NAME, SEVERITY, DETAILS)
    SELECT :run_id, 'EXPENSES', "EXPENSE_ID", _ROW_NUM, 'DUPLICATE_ID', 'expense_id', 'ERROR', 'Primary key appears more than once'
    FROM STAGING.EXPENSES WHERE "EXPENSE_ID" IS NOT NULL
    QUALIFY ROW_NUMBER() OVER (PARTITION BY "EXPENSE_ID" ORDER BY _ROW_NUM) > 1;
  INSERT INTO STAGING.DQ_ISSUES (RUN_ID, TABLE_NAME, RECORD_ID, ROW_NUM, RULE_CODE, COLUMN_NAME, SEVERITY, DETAILS)
    SELECT :run_id, 'EXPENSES', s."EXPENSE_ID", s._ROW_NUM, 'FK_ORPHAN', 'department_id', 'ERROR',
           'No matching departments.department_id in CURATED: ' || s."DEPARTMENT_ID"
    FROM STAGING.EXPENSES s
    WHERE s."DEPARTMENT_ID" IS NOT NULL
      AND NOT EXISTS (SELECT 1 FROM CURATED.DEPARTMENTS p WHERE p."DEPARTMENT_ID" = s."DEPARTMENT_ID");
  INSERT INTO CURATED.EXPENSES ("EXPENSE_ID", "DEPARTMENT_ID", "CATEGORY", "EXPENSE_DATE", "AMOUNT", "DESCRIPTION")
    SELECT "EXPENSE_ID", "DEPARTMENT_ID", "CATEGORY", "EXPENSE_DATE", "AMOUNT", "DESCRIPTION" FROM STAGING.EXPENSES s
    WHERE NOT EXISTS (SELECT 1 FROM STAGING.DQ_ISSUES i
                      WHERE i.RUN_ID = :run_id AND i.TABLE_NAME = 'EXPENSES' AND i.SEVERITY = 'ERROR'
                        AND i.ROW_NUM = s._ROW_NUM)
      AND NOT EXISTS (SELECT 1 FROM CURATED.EXPENSES c WHERE c."EXPENSE_ID" = s."EXPENSE_ID");
  INSERT INTO STAGING.PIPELINE_RUNS (RUN_ID, TABLE_NAME, RAW_ROWS, CURATED_ROWS, ERROR_ROWS)
    SELECT :run_id, 'EXPENSES',
      (SELECT COUNT(*) FROM STAGING.EXPENSES),
      (SELECT COUNT(*) FROM CURATED.EXPENSES),
      (SELECT COUNT(DISTINCT ROW_NUM) FROM STAGING.DQ_ISSUES WHERE RUN_ID = :run_id AND TABLE_NAME = 'EXPENSES' AND SEVERITY = 'ERROR');
  CREATE OR REPLACE TABLE STAGING.BILLING AS
    SELECT
      NULLIF(TRIM("BILL_ID"), '') AS "BILL_ID",
      NULLIF(TRIM("ENCOUNTER_ID"), '') AS "ENCOUNTER_ID",
      NULLIF(TRIM("PATIENT_ID"), '') AS "PATIENT_ID",
      TRY_TO_DECIMAL(NULLIF(TRIM("AMOUNT"), ''), 14, 2) AS "AMOUNT",
      NULLIF(TRIM("PAYER"), '') AS "PAYER",
      NULLIF(TRIM("BILL_STATUS"), '') AS "BILL_STATUS",
      TRY_TO_DATE(NULLIF(TRIM("BILLED_ON"), ''), 'YYYY-MM-DD') AS "BILLED_ON",
      ARRAY_CONSTRUCT_COMPACT(IFF(NULLIF(TRIM("AMOUNT"), '') IS NOT NULL AND TRY_TO_DECIMAL(NULLIF(TRIM("AMOUNT"), ''), 14, 2) IS NULL, 'amount', NULL), IFF(NULLIF(TRIM("BILLED_ON"), '') IS NOT NULL AND TRY_TO_DATE(NULLIF(TRIM("BILLED_ON"), ''), 'YYYY-MM-DD') IS NULL, 'billed_on', NULL)) AS _CAST_FAIL,
      ROW_NUMBER() OVER (ORDER BY _FILE, "BILL_ID") AS _ROW_NUM,
      _FILE
    FROM RAW.BILLING;
  INSERT INTO STAGING.DQ_ISSUES (RUN_ID, TABLE_NAME, RECORD_ID, ROW_NUM, RULE_CODE, COLUMN_NAME, SEVERITY, DETAILS)
    SELECT :run_id, 'BILLING', "BILL_ID", _ROW_NUM, 'INVALID_FORMAT', f.value::STRING, 'ERROR',
           'Value could not be converted to the expected type'
    FROM STAGING.BILLING, LATERAL FLATTEN(_CAST_FAIL) f;
  INSERT INTO STAGING.DQ_ISSUES (RUN_ID, TABLE_NAME, RECORD_ID, ROW_NUM, RULE_CODE, COLUMN_NAME, SEVERITY, DETAILS)
    SELECT :run_id, 'BILLING', "BILL_ID", _ROW_NUM, 'REQUIRED_MISSING', 'bill_id', 'ERROR', 'Required field is empty'
    FROM STAGING.BILLING WHERE "BILL_ID" IS NULL AND NOT ARRAY_CONTAINS('bill_id'::VARIANT, _CAST_FAIL);
  INSERT INTO STAGING.DQ_ISSUES (RUN_ID, TABLE_NAME, RECORD_ID, ROW_NUM, RULE_CODE, COLUMN_NAME, SEVERITY, DETAILS)
    SELECT :run_id, 'BILLING', "BILL_ID", _ROW_NUM, 'REQUIRED_MISSING', 'encounter_id', 'ERROR', 'Required field is empty'
    FROM STAGING.BILLING WHERE "ENCOUNTER_ID" IS NULL AND NOT ARRAY_CONTAINS('encounter_id'::VARIANT, _CAST_FAIL);
  INSERT INTO STAGING.DQ_ISSUES (RUN_ID, TABLE_NAME, RECORD_ID, ROW_NUM, RULE_CODE, COLUMN_NAME, SEVERITY, DETAILS)
    SELECT :run_id, 'BILLING', "BILL_ID", _ROW_NUM, 'REQUIRED_MISSING', 'patient_id', 'ERROR', 'Required field is empty'
    FROM STAGING.BILLING WHERE "PATIENT_ID" IS NULL AND NOT ARRAY_CONTAINS('patient_id'::VARIANT, _CAST_FAIL);
  INSERT INTO STAGING.DQ_ISSUES (RUN_ID, TABLE_NAME, RECORD_ID, ROW_NUM, RULE_CODE, COLUMN_NAME, SEVERITY, DETAILS)
    SELECT :run_id, 'BILLING', "BILL_ID", _ROW_NUM, 'REQUIRED_MISSING', 'amount', 'ERROR', 'Required field is empty'
    FROM STAGING.BILLING WHERE "AMOUNT" IS NULL AND NOT ARRAY_CONTAINS('amount'::VARIANT, _CAST_FAIL);
  INSERT INTO STAGING.DQ_ISSUES (RUN_ID, TABLE_NAME, RECORD_ID, ROW_NUM, RULE_CODE, COLUMN_NAME, SEVERITY, DETAILS)
    SELECT :run_id, 'BILLING', "BILL_ID", _ROW_NUM, 'REQUIRED_MISSING', 'payer', 'ERROR', 'Required field is empty'
    FROM STAGING.BILLING WHERE "PAYER" IS NULL AND NOT ARRAY_CONTAINS('payer'::VARIANT, _CAST_FAIL);
  INSERT INTO STAGING.DQ_ISSUES (RUN_ID, TABLE_NAME, RECORD_ID, ROW_NUM, RULE_CODE, COLUMN_NAME, SEVERITY, DETAILS)
    SELECT :run_id, 'BILLING', "BILL_ID", _ROW_NUM, 'REQUIRED_MISSING', 'bill_status', 'ERROR', 'Required field is empty'
    FROM STAGING.BILLING WHERE "BILL_STATUS" IS NULL AND NOT ARRAY_CONTAINS('bill_status'::VARIANT, _CAST_FAIL);
  INSERT INTO STAGING.DQ_ISSUES (RUN_ID, TABLE_NAME, RECORD_ID, ROW_NUM, RULE_CODE, COLUMN_NAME, SEVERITY, DETAILS)
    SELECT :run_id, 'BILLING', "BILL_ID", _ROW_NUM, 'REQUIRED_MISSING', 'billed_on', 'ERROR', 'Required field is empty'
    FROM STAGING.BILLING WHERE "BILLED_ON" IS NULL AND NOT ARRAY_CONTAINS('billed_on'::VARIANT, _CAST_FAIL);
  INSERT INTO STAGING.DQ_ISSUES (RUN_ID, TABLE_NAME, RECORD_ID, ROW_NUM, RULE_CODE, COLUMN_NAME, SEVERITY, DETAILS)
    SELECT :run_id, 'BILLING', "BILL_ID", _ROW_NUM, 'DUPLICATE_ID', 'bill_id', 'ERROR', 'Primary key appears more than once'
    FROM STAGING.BILLING WHERE "BILL_ID" IS NOT NULL
    QUALIFY ROW_NUMBER() OVER (PARTITION BY "BILL_ID" ORDER BY _ROW_NUM) > 1;
  INSERT INTO STAGING.DQ_ISSUES (RUN_ID, TABLE_NAME, RECORD_ID, ROW_NUM, RULE_CODE, COLUMN_NAME, SEVERITY, DETAILS)
    SELECT :run_id, 'BILLING', s."BILL_ID", s._ROW_NUM, 'FK_ORPHAN', 'encounter_id', 'ERROR',
           'No matching encounters.encounter_id in CURATED: ' || s."ENCOUNTER_ID"
    FROM STAGING.BILLING s
    WHERE s."ENCOUNTER_ID" IS NOT NULL
      AND NOT EXISTS (SELECT 1 FROM CURATED.ENCOUNTERS p WHERE p."ENCOUNTER_ID" = s."ENCOUNTER_ID");
  INSERT INTO STAGING.DQ_ISSUES (RUN_ID, TABLE_NAME, RECORD_ID, ROW_NUM, RULE_CODE, COLUMN_NAME, SEVERITY, DETAILS)
    SELECT :run_id, 'BILLING', s."BILL_ID", s._ROW_NUM, 'FK_ORPHAN', 'patient_id', 'ERROR',
           'No matching patients.patient_id in CURATED: ' || s."PATIENT_ID"
    FROM STAGING.BILLING s
    WHERE s."PATIENT_ID" IS NOT NULL
      AND NOT EXISTS (SELECT 1 FROM CURATED.PATIENTS p WHERE p."PATIENT_ID" = s."PATIENT_ID");
  INSERT INTO STAGING.DQ_ISSUES (RUN_ID, TABLE_NAME, RECORD_ID, ROW_NUM, RULE_CODE, COLUMN_NAME, SEVERITY, DETAILS)
    SELECT :run_id, 'BILLING', "BILL_ID", _ROW_NUM, 'OUT_OF_RANGE', NULL, 'ERROR', 'Failed check: amount < 0'
    FROM STAGING.BILLING WHERE amount < 0;
  INSERT INTO CURATED.BILLING ("BILL_ID", "ENCOUNTER_ID", "PATIENT_ID", "AMOUNT", "PAYER", "BILL_STATUS", "BILLED_ON")
    SELECT "BILL_ID", "ENCOUNTER_ID", "PATIENT_ID", "AMOUNT", "PAYER", "BILL_STATUS", "BILLED_ON" FROM STAGING.BILLING s
    WHERE NOT EXISTS (SELECT 1 FROM STAGING.DQ_ISSUES i
                      WHERE i.RUN_ID = :run_id AND i.TABLE_NAME = 'BILLING' AND i.SEVERITY = 'ERROR'
                        AND i.ROW_NUM = s._ROW_NUM)
      AND NOT EXISTS (SELECT 1 FROM CURATED.BILLING c WHERE c."BILL_ID" = s."BILL_ID");
  INSERT INTO STAGING.PIPELINE_RUNS (RUN_ID, TABLE_NAME, RAW_ROWS, CURATED_ROWS, ERROR_ROWS)
    SELECT :run_id, 'BILLING',
      (SELECT COUNT(*) FROM STAGING.BILLING),
      (SELECT COUNT(*) FROM CURATED.BILLING),
      (SELECT COUNT(DISTINCT ROW_NUM) FROM STAGING.DQ_ISSUES WHERE RUN_ID = :run_id AND TABLE_NAME = 'BILLING' AND SEVERITY = 'ERROR');
  RETURN run_id;
END;
$$;
